import React, { useState, useEffect } from 'react'
import { Prompt } from 'react-router'
import { Row, Col, Steps, Button, Icon } from 'antd'
import LayoutContentWrapper from '../../../../../../components/utility/layoutWrapper'
import LayoutContent from '../../../../../../components/utility/layoutContent'
import { ProductContainer } from './index.style'
import StepTwo from './StepTwo'
import StepOne from './StepOne'
import StepThree from './StepThree'
import { clearSessionStorageKeys } from './StepThree/utility'

const { Step } = Steps

const steps = [
  {
    title: 'Add Product',
    content: (props) => <StepOne {...props} />
  },
  {
    title: 'Add Plan',
    content: (props) => <StepTwo {...props} />
  },
  {
    title: 'Review',
    content: (props) => <StepThree {...props} />
  }
]

const AddProductPlansAndTSI = ({ history, match, ...props }) => {
  const [current, setCurrent] = useState(0)
  const goToNextStep = () => setCurrent(current => ++current)
  const goToPreviousStep = () => setCurrent(current => --current)
  const [canDeactivate, setCanDeactivate] = useState(false)

  const handleGoBack = () => {
    if (current === 0) {
      history.push(`/employee-benefits/company-list/${match.params.id}/`)
    } else {
      goToPreviousStep()
    }
  }

  useEffect(() => {
    if (canDeactivate) {
      history.push(`/employee-benefits/company-list/${match.params.id}/`)
    }
  }, [canDeactivate, history, match])

  useEffect(() => {
    return () => {
      clearSessionStorageKeys([
        'eb-product-step-one-data',
        'eb-product-step-one-to-be-sent-values',
        'plansData',
        'editorsState',
        'eb-product-step-one-form',
        'eb-product-step-one-bg-keys',
        'eb-product-step-one-benefits',
        'eb-product-default-benefit-groups',
        'eb-products-form-fill-mode'
      ])
    }
  }, [])
  return (
    <ProductContainer>
      <Prompt
        when={!canDeactivate}
        message='You changes will be lost if you leave this page, are you sure you want to leave?'
      />
      <div className='back-btn-container'>
        <Button
          onClick={handleGoBack}
        >
          <Icon type='arrow-left' /> Back
        </Button>
      </div>
      <Row type='flex' justify='center'>
        <Col span={12}>
          <Steps current={current} size='small'>
            {steps.map((item, index) => (
              <Step key={item.title} title={item.title} />
            ))}
          </Steps>
        </Col>
      </Row>
      <LayoutContentWrapper>
        <LayoutContent>
          {
            steps[current].content({
              next: goToNextStep,
              prev: goToPreviousStep,
              setCanDeactivate
            })
          }
        </LayoutContent>
      </LayoutContentWrapper>
    </ProductContainer>
  )
}
export default AddProductPlansAndTSI
