import { useCallback, useEffect, useRef } from 'react'
import { Button, Icon, Popconfirm, Row, Typography, Upload } from 'antd'
import xlsx from 'xlsx'
import ExportExcel from '../../../../../../../../components/ExportExcel'
import { BENEFITS, BENEFIT_GROUPS, BENEFIT_NAME, IS_SELECTED, STATE_UPDATED_FROM_EXCEL } from '../../../../constants'
import { ColTextAlignCenter } from '../../../../../../../../CommonComponents/index.style'
import { ExcelUploadContainer } from './index.style'
import { parseDataFromExcel, setFormDataInSessionStorage } from './utility'
import ebUrls from '../../../../../../../../../../../request/urls/employeeBenefit'

const { Title } = Typography

const ExcelUpload = ({ benefitGroupKeys, defaultBenefitGroups, setStateFromExcel, form, unsetStateUpdatedFromExcel }) => {
  const parsedExcelDataRef = useRef()
  const { setFieldsValue } = form
  const allowPropogate = useRef(false)
  const handleFileChange = useCallback(({ file }) => {
    if (defaultBenefitGroups) {
      if (file?.status !== 'removed') {
        const reader = new FileReader()
        reader.onload = (e) => {
          const data = e.target.result
          const workbook = xlsx.read(data, { type: 'binary' })
          const benefitGroupsWorksheet = workbook.Sheets[workbook.SheetNames[0]]
          const benefitGroupsFromExcel = xlsx.utils.sheet_to_json(benefitGroupsWorksheet)
          const parsedExcelData = parseDataFromExcel(benefitGroupsFromExcel, defaultBenefitGroups)
          parsedExcelDataRef.current = parsedExcelData
          setFormDataInSessionStorage(parsedExcelData)
          setStateFromExcel(parsedExcelData)
        }
        reader.readAsBinaryString(file)
      }
    }
  }, [defaultBenefitGroups, setStateFromExcel])

  useEffect(() => {
    if (benefitGroupKeys[STATE_UPDATED_FROM_EXCEL]) {
      const parsedData = parsedExcelDataRef.current
      parsedData.forEach((benefitGroup, bgKey) => {
        if (benefitGroup.autoSelected) {
          const bgCheckboxFormKey = `${BENEFIT_GROUPS}.bg${bgKey}.${IS_SELECTED}`
          setFieldsValue({ [bgCheckboxFormKey]: true })
        }
        benefitGroup.benefits.forEach((benefit, benefitKey) => {
          const benefitNameFormKey = `${BENEFIT_GROUPS}.bg${bgKey}.${BENEFITS}.b${benefitKey}.${BENEFIT_NAME}`
          setFieldsValue({ [benefitNameFormKey]: benefit })
        })
      })
      unsetStateUpdatedFromExcel()
    }
  }, [benefitGroupKeys, setFieldsValue, unsetStateUpdatedFromExcel])

  return (
    <ExcelUploadContainer>
      <Row type='flex' align='middle'>
        <ColTextAlignCenter span={24}>
          <Title level={4}>Autofill Form Data From Excel</Title>
        </ColTextAlignCenter>
        <ColTextAlignCenter className='download-container' span={24}>
          <ExportExcel
            buttonType='link'
            buttonContent={<>Download sample <Icon type='download' /></>}
            buttonSize='small'
            url={ebUrls.downloadSampleTemplateForProduct}
          />
        </ColTextAlignCenter>
        <ColTextAlignCenter className='upload-container' span={24}>
          <Upload
            multiple={false}
            onChange={handleFileChange}
            beforeUpload={() => false}
          >
            <div onClick={e => {
              if (allowPropogate.current) {
                allowPropogate.current = false
              } else {
                e.stopPropagation()
              }
            }}
            >
              <Popconfirm
                onConfirm={() => { allowPropogate.current = true }}
                title={<>Previous filled data will be removed. <br />Are you sure you want to continue?</>}
              >
                <Button type='primary' block>
                  <Icon type='upload' /> Select File
                </Button>
              </Popconfirm>
            </div>
          </Upload>
        </ColTextAlignCenter>
      </Row>
    </ExcelUploadContainer>
  )
}
export default ExcelUpload
