import { COLUMN_NAMES } from './constants'

const getLimitType = (limitType) => {
  const limitTypeInSmallCase = String(limitType).toLowerCase()
  if (['yearly', 'inner'].includes(limitTypeInSmallCase)) {
    return limitTypeInSmallCase
  }
}

export const parseDataFromExcel = (benefitGroupsFromExcel, defaultBenefitGroups) => {
  const parsedBgData = []
  if (Array.isArray(defaultBenefitGroups)) {
    defaultBenefitGroups.forEach(({ group_name: groupName }) => {
      parsedBgData.push({
        name: groupName,
        benefits: [],
        plans: []
      })
    })
  }
  benefitGroupsFromExcel.forEach(bgGroupRow => {
    if (
      !(
        bgGroupRow[COLUMN_NAMES.benefitGroup] &&
        bgGroupRow[COLUMN_NAMES.benefit] &&
        bgGroupRow[COLUMN_NAMES.planName]
      )
    ) return
    let existingBgIndex = -1
    for (let i = 0; i < parsedBgData.length; i++) {
      if (parsedBgData[i].name === bgGroupRow[COLUMN_NAMES.benefitGroup]) {
        existingBgIndex = i
      }
    }
    if (existingBgIndex >= 0) {
      parsedBgData[existingBgIndex].autoSelected = true
      if (!parsedBgData[existingBgIndex].benefits.includes(bgGroupRow[COLUMN_NAMES.benefit])) {
        parsedBgData[existingBgIndex].benefits.push(bgGroupRow[COLUMN_NAMES.benefit])
      }
      if (bgGroupRow[COLUMN_NAMES.TNC]) {
        parsedBgData[existingBgIndex].tnc = bgGroupRow[COLUMN_NAMES.TNC]
      }
      if (bgGroupRow[COLUMN_NAMES.limitType]) {
        parsedBgData[existingBgIndex].limitType = getLimitType(bgGroupRow[COLUMN_NAMES.limitType])
      }
      let existingPlansIndex = -1
      const existingPlans = parsedBgData[existingBgIndex].plans
      for (let i = 0; i < existingPlans.length; i++) {
        if (existingPlans[i].name === bgGroupRow[COLUMN_NAMES.planName]) {
          existingPlansIndex = i
        }
      }
      if (existingPlansIndex >= 0) {
        // To Filter out redundant plan benefits
        parsedBgData[existingBgIndex].plans[existingPlansIndex].benefits = parsedBgData[existingBgIndex].plans[existingPlansIndex].benefits
          .filter(({ benefit }) => benefit !== bgGroupRow[COLUMN_NAMES.benefit])
        parsedBgData[existingBgIndex].plans[existingPlansIndex].benefits.push({
          benefit: bgGroupRow[COLUMN_NAMES.benefit],
          tsi: bgGroupRow[COLUMN_NAMES.tsi]
        })
      } else {
        existingPlans.push({
          name: bgGroupRow[COLUMN_NAMES.planName],
          yearlyLimit: bgGroupRow[COLUMN_NAMES.yearlyLimit],
          benefits: [{
            benefit: bgGroupRow[COLUMN_NAMES.benefit],
            tsi: bgGroupRow[COLUMN_NAMES.tsi]
          }]
        })
      }
    } else {
      let limitType
      if (bgGroupRow[COLUMN_NAMES.limitType]) {
        limitType = getLimitType(bgGroupRow[COLUMN_NAMES.limitType])
      }
      parsedBgData.push({
        name: bgGroupRow[COLUMN_NAMES.benefitGroup],
        benefits: [bgGroupRow[COLUMN_NAMES.benefit]],
        tnc: bgGroupRow[COLUMN_NAMES.TNC],
        limitType,
        autoSelected: true,
        plans: [
          {
            name: bgGroupRow[COLUMN_NAMES.planName],
            yearlyLimit: bgGroupRow[COLUMN_NAMES.yearlyLimit],
            benefits: [{
              benefit: bgGroupRow[COLUMN_NAMES.benefit],
              tsi: bgGroupRow[COLUMN_NAMES.tsi]
            }]
          }]
      })
    }
  })
  return parsedBgData
}

export const setFormDataInSessionStorage = (parsedBgData) => {
  const plansData = {}
  parsedBgData.forEach((bgData, bgKey) => {
    if (!bgData.autoSelected) return
    plansData[bgKey] = [
      { limit_type: bgData.limitType }
    ]
    bgData.plans.forEach(({ name, yearlyLimit, benefits }) => {
      const planData = { name }
      benefits.forEach(({ benefit, tsi }) => {
        const benefitKey = bgData.benefits.indexOf(benefit)
        planData[`Benefit_${benefitKey}`] = tsi
      })
      planData['Yearly Limit'] = yearlyLimit
      plansData[bgKey].push(planData)
    })
  })
  window.sessionStorage.setItem('plansData', JSON.stringify(plansData))
}
