import { useCallback } from 'react'
import { addBenefitKeyAction, addNewBenefitGroupAction, removeBenefitGroupKeyAction, removeBenefitKeyAction, setStateFromExcelAction, unsetStateUpdatedFromExcelAction } from './actions'

export const useManageBenefitGroupKeys = (dispatch) => {
  const addBenefitGroupKey = (bgName, bgSlug) => dispatch(addNewBenefitGroupAction(bgName, bgSlug))
  const removeBenefitGroupKey = bgKey => dispatch(removeBenefitGroupKeyAction(bgKey))
  const addBenefitKey = bgKey => dispatch(addBenefitKeyAction(bgKey))
  const removeBenefitKey = (bgKey, benefitKey) => dispatch(removeBenefitKeyAction(bgKey, benefitKey))
  const setStateFromExcel = useCallback((bgData) => dispatch(setStateFromExcelAction(bgData)), [dispatch])
  const unsetStateUpdatedFromExcel = useCallback(() => dispatch(unsetStateUpdatedFromExcelAction()), [dispatch])
  return { addBenefitGroupKey, removeBenefitGroupKey, addBenefitKey, removeBenefitKey, setStateFromExcel, unsetStateUpdatedFromExcel }
}
