import { getFromSessionStorage } from '../../../../../../../helpers/utility'
import { BENEFIT_GROUPS, BG_IDENTIFIER, BG_NAME, BG_SLUG } from '../StepOne/constants'

export const formatIntl = (number) => {
  if (!number) return
  return new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(number)
}

export const getBenefitGroups = () => {
  const benefitGroups = []
  const storedFormData = getFromSessionStorage('eb-product-step-one-to-be-sent-values')
  if (storedFormData && storedFormData[BENEFIT_GROUPS]) {
    const { [BENEFIT_GROUPS]: benefitGroupsStored } = storedFormData
    for (const benefitGroup of Object.values(benefitGroupsStored)) {
      benefitGroups.push({
        name: benefitGroup[BG_NAME],
        identifier: benefitGroup[BG_IDENTIFIER],
        slug: benefitGroup[BG_SLUG],
        benefits: Object.values(benefitGroup.benefits).map(({ benefitName, benefitIdentifier }) => ({
          name: benefitName,
          identifier: `Benefit_${benefitIdentifier}`
        }))
      })
    }
    return benefitGroups
  }
  return []
}

export const clearSessionStorageKeys = (keys = []) => {
  keys.forEach(key => window.sessionStorage.removeItem(key))
}

export { getFromSessionStorage }
