import { BENEFIT_KEY, BENEFIT_KEYS, BENEFIT_KEY_COUNTER, BG_KEY, BG_KEYS, BG_KEY_COUNTER, BG_NAME, BG_SLUG, STATE_UPDATED_FROM_EXCEL } from '../constants'
import { ADD_BENEFIT_GROUP_KEY, ADD_BENEFIT_KEY, REMOVE_BENEFIT_GROUP_KEY, REMOVE_BENEFIT_KEY, SET_STATE_FROM_EXCEL, UNSET_STATE_UPDATED_FROM_EXCEL } from './actions'

export const benefitGroupKeyReducer = (state, action) => {
  const { [BG_KEY_COUNTER]: bgKeyCounter } = state
  const { payload } = action
  const { [BG_KEY]: bgKey, [BENEFIT_KEY]: benefitKey, [BG_SLUG]: bgSlug } = payload || {}
  switch (action.type) {
    case ADD_BENEFIT_GROUP_KEY:
      return {
        [BG_KEY_COUNTER]: bgKeyCounter + 1,
        [BG_KEYS]: [
          ...state[BG_KEYS],
          {
            [BG_KEY]: bgKeyCounter + 1,
            [BG_NAME]: payload[BG_NAME],
            [BENEFIT_KEY_COUNTER]: 0,
            [BENEFIT_KEYS]: [0],
            [BG_SLUG]: bgSlug
          }
        ]
      }
    case REMOVE_BENEFIT_GROUP_KEY:
      return {
        ...state,
        [BG_KEYS]: state.BG_KEYS.filter(({ [BG_KEY]: bgKey }) => bgKey !== payload[BG_KEY])
      }
    case ADD_BENEFIT_KEY:
      return {
        ...state,
        [BG_KEYS]: state[BG_KEYS].map(bgKeys => {
          if (bgKeys[BG_KEY] !== bgKey) {
            return bgKeys
          }
          const nextBenefitKey = bgKeys[BENEFIT_KEY_COUNTER] + 1
          return {
            ...bgKeys,
            [BENEFIT_KEY_COUNTER]: nextBenefitKey,
            [BENEFIT_KEYS]: [...bgKeys[BENEFIT_KEYS], nextBenefitKey]
          }
        })
      }
    case REMOVE_BENEFIT_KEY:
      return {
        ...state,
        [BG_KEYS]: state[BG_KEYS].map(bgKeys => {
          if (bgKeys[BG_KEY] !== bgKey) {
            return bgKeys
          }
          return {
            ...bgKeys,
            [BENEFIT_KEYS]: bgKeys[BENEFIT_KEYS].filter(benefitKeyExisting => benefitKeyExisting !== benefitKey)
          }
        })
      }
    case UNSET_STATE_UPDATED_FROM_EXCEL:
      return getStateAfterUnsettingStateUpdatedFromExcel(state)
    case SET_STATE_FROM_EXCEL:
      return getStateFromExcel(payload)
    default:
      return state
  }
}

function getStateFromExcel (bgData) {
  let bgKeyCounter = 0
  const BG_STATE = {
    [BG_KEYS]: []
  }
  bgData.forEach(({ name, benefits, ...benefitGroup }) => {
    const bgStateData = {
      [BG_NAME]: name,
      [BG_KEY]: bgKeyCounter++,
      [BENEFIT_KEY_COUNTER]: benefits.length,
      [BENEFIT_KEYS]: benefits.length ? benefits.map((item, index) => index) : [0]
    }
    BG_STATE[BG_KEYS].push(bgStateData)
  })
  BG_STATE[BG_KEY_COUNTER] = bgKeyCounter
  BG_STATE[STATE_UPDATED_FROM_EXCEL] = true
  return BG_STATE
}

function getStateAfterUnsettingStateUpdatedFromExcel (state) {
  const clonedState = { ...state }
  delete clonedState[STATE_UPDATED_FROM_EXCEL]
  return clonedState
}
