/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useReducer, useRef } from 'react'
import { Form, notification, Spin } from 'antd'
import { BENEFIT_GROUPS, COVERAGE_END_DATE, IS_SELECTED, TOTAL_PREMIUM } from './constants'
import PackageForm from './components/PackageForm'
import { benefitGroupKeyReducer } from './state/reducers'
import { useManageBenefitGroupKeys } from './state/hooks'
import { useDefaultBenefitGroups } from '../../../../state/Products/hooks/useProductsContext'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useResetState } from '../../../../state/hooks'
import { getInitialBgKeys } from './utility'
import { getFromSessionStorage } from '../StepThree/utility'
import { useParams } from 'react-router'
import moment from 'moment-timezone'

const StepOne = ({ form, ...props }) => {
  const { getFieldDecorator } = form
  const [benefitGroupKeys, dispatch] = useReducer(benefitGroupKeyReducer, getInitialBgKeys())
  const { addBenefitGroupKey, removeBenefitGroupKey, addBenefitKey, removeBenefitKey, setStateFromExcel, unsetStateUpdatedFromExcel } = useManageBenefitGroupKeys(dispatch)
  const { defaultBenefitGroupsRequest, defaultBenefitGroupsData } = useDefaultBenefitGroups()
  const params = useParams()
  const [{ DEFAULT_BENEFIT_GROUPS_LOADER, HOSPITAL_PROVIDER_LIST_LOADER }] = useLoaderContextValue()
  const { resetState } = useResetState()
  const defaultBgData = useRef()

  const handleSubmit = (e) => {
    e.preventDefault()
    form.resetFields(['newItem'])
    form.validateFields((err, values) => {
      if (!err) {
        const { [BENEFIT_GROUPS]: benefitGroups, ...toBeSentValues } = values
        toBeSentValues[BENEFIT_GROUPS] = {}
        for (const key in benefitGroups) {
          if (benefitGroups[key][IS_SELECTED]) {
            toBeSentValues[BENEFIT_GROUPS][key] = benefitGroups[key]
          }
        }
        if (!Object.values(toBeSentValues.benefit_groups).length) {
          notification.error({
            message: 'Cannot process',
            description: 'Please select at least one benefit group'
          })
          return
        }
        toBeSentValues[TOTAL_PREMIUM] = values[TOTAL_PREMIUM] && Number(String(values[TOTAL_PREMIUM]).split(/\./g).join('').replace(',', '.'))
        values[TOTAL_PREMIUM] = toBeSentValues[TOTAL_PREMIUM]
        values[COVERAGE_END_DATE] = values[COVERAGE_END_DATE]?.format('YYYY-MM-DD')
        toBeSentValues[COVERAGE_END_DATE] = toBeSentValues[COVERAGE_END_DATE]?.format('YYYY-MM-DD')
        toBeSentValues.reimbursement_percentage = toBeSentValues.reimbursement_percentage || null
        toBeSentValues.company_id = params.id
        window.sessionStorage.setItem('eb-product-step-one-form', JSON.stringify(values, (k, v) => v === undefined ? null : v))
        window.sessionStorage.setItem('eb-product-step-one-to-be-sent-values', JSON.stringify(toBeSentValues, (k, v) => v === undefined ? null : v))
        window.sessionStorage.setItem('eb-product-step-one-bg-keys', JSON.stringify(benefitGroupKeys))
        props.next()
      }
    })
  }

  useEffect(() => {
    if (defaultBenefitGroupsData && defaultBenefitGroupsData.data) {
      const { data } = defaultBenefitGroupsData
      data.forEach(({ group_name: groupName, slug }) => addBenefitGroupKey(groupName, slug))
      defaultBgData.current = defaultBenefitGroupsData.data
      window.sessionStorage.setItem('eb-product-default-benefit-groups', JSON.stringify(defaultBenefitGroupsData.data))
      resetState(['defaultBenefitGroupsData'])
    } else {
      const defaultBenefitGroups = getFromSessionStorage('eb-product-default-benefit-groups')
      if (defaultBenefitGroups) {
        defaultBgData.current = defaultBenefitGroups
      }
    }
  }, [defaultBenefitGroupsData])

  useEffect(() => {
    const storedFormData = getFromSessionStorage('eb-product-step-one-form') // Call default bg request only if it has not been called already.
    if (!storedFormData) {
      defaultBenefitGroupsRequest()
    } else {
      const { [COVERAGE_END_DATE]: coverageEndDate, ...restFields } = storedFormData
      form.setFieldsValue(restFields)
      form.setFieldsValue({ [COVERAGE_END_DATE]: moment(coverageEndDate) })
    }
  }, [])

  return (
    <Spin spinning={!!DEFAULT_BENEFIT_GROUPS_LOADER || !!HOSPITAL_PROVIDER_LIST_LOADER}>
      <PackageForm
        handleSubmit={handleSubmit}
        getFieldDecorator={getFieldDecorator}
        form={form}
        benefitGroupKeys={benefitGroupKeys}
        onAddBenefitGroupKey={addBenefitGroupKey}
        onRemoveBenefitGroupKey={removeBenefitGroupKey}
        onAddBenefitKey={addBenefitKey}
        onRemoveBenefitKey={removeBenefitKey}
        defaultBenefitGroups={defaultBgData.current}
        setStateFromExcel={setStateFromExcel}
        unsetStateUpdatedFromExcel={unsetStateUpdatedFromExcel}
      />
    </Spin>
  )
}
export default Form.create({ name: 'add-product-step-one' })(StepOne)
