import { BENEFIT_KEY, BG_KEY, BG_NAME, BG_SLUG } from '../constants'

export const ADD_BENEFIT_GROUP_KEY = 'ADD_BENEFIT_GROUP_KEY'
export const REMOVE_BENEFIT_GROUP_KEY = 'REMOVE_BENEFIT_GROUP_KEY'
export const ADD_BENEFIT_KEY = 'ADD_BENEFIT_KEY'
export const REMOVE_BENEFIT_KEY = 'REMOVE_BENEFIT_KEY'
export const SET_STATE_FROM_EXCEL = 'SET_STATE_FROM_EXCEL'
export const UNSET_STATE_UPDATED_FROM_EXCEL = 'UNSET_STATE_UPDATED_FROM_EXCEL'

export const addNewBenefitGroupAction = (bgName, bgSlug) => ({
  type: ADD_BENEFIT_GROUP_KEY,
  payload: {
    [BG_NAME]: bgName,
    [BG_SLUG]: bgSlug
  }
})

export const removeBenefitGroupKeyAction = (bgKey) => ({
  type: REMOVE_BENEFIT_GROUP_KEY,
  payload: {
    [BG_KEY]: bgKey
  }
})

export const addBenefitKeyAction = bgKey => ({
  type: ADD_BENEFIT_KEY,
  payload: {
    [BG_KEY]: bgKey
  }
})

export const removeBenefitKeyAction = (bgKey, benefitKey) => ({
  type: REMOVE_BENEFIT_KEY,
  payload: {
    [BG_KEY]: bgKey,
    [BENEFIT_KEY]: benefitKey
  }
})

export const setStateFromExcelAction = (bgData) => ({
  type: SET_STATE_FROM_EXCEL,
  payload: bgData
})

export const unsetStateUpdatedFromExcelAction = (payload = {}) => ({
  type: UNSET_STATE_UPDATED_FROM_EXCEL,
  payload
})
