/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react'
import {
  Form,
  Row,
  Col,
  Typography,
  Select,
  Input,
  Checkbox,
  Icon,
  Button,
  notification,
  Radio,
  DatePicker
} from 'antd'
import { ColTextAlignCenter, ColTextAlignRight, RowWithMargin } from '../../../../../../CommonComponents/index.style'
import { useResetState, useProviderList } from '../../../../../../../../state/employeeBenefit/hooks/useEB'
import { useError } from '../../../../../../../../../state/error/hooks/useError'
import CustomNumberFormat from '../../../../../../CommonComponents/CustomNumberFormat'
import { useCompanyDetails } from '../../../../../../state/Products/hooks/useProductsContext'
import { divideArrayIntoSubArraysOfTwo } from '../../../../../../../../../helpers/utility'
import { useErrorContextValue, useGet } from '@pasarpolis/common-react-hooks'
import { BENEFITS, BENEFIT_GROUPS, BENEFIT_IDENTIFIER, BENEFIT_KEYS, BENEFIT_NAME, BG_IDENTIFIER, BG_KEY, BG_KEYS, BG_NAME, BG_SLUG, IS_SELECTED, STATE_UPDATED_FROM_EXCEL, TOTAL_PREMIUM } from '../../constants'
import { useParams } from 'react-router'
import { stepOneValidationRules } from './validations'
import ExcelUpload from './components/ExcelUpload'
import { BenefitGroupContainer, PackageFormWrapper } from './index.style'
import { FILL_DATA_MODE, getInitialFillDataModeState } from './constants'
import { productsApiConfig } from '../../../../../../state/Products/apiConfig'
import moment from 'moment-timezone'

const { Title } = Typography
const { Option } = Select

export default function PackageForm ({
  handleSubmit,
  getFieldDecorator,
  form,
  benefitGroupKeys,
  onAddBenefitGroupKey,
  onRemoveBenefitGroupKey,
  onAddBenefitKey,
  onRemoveBenefitKey,
  defaultBenefitGroups,
  setStateFromExcel,
  unsetStateUpdatedFromExcel
}) {
  const [resetEbState] = useResetState()
  const { resetError } = useError()
  const parmas = useParams()
  const { companyDetailRequest, companyDetailData } = useCompanyDetails()
  const [{ providerListRequest, providerListData }] = useProviderList()
  const [{ COMPANY_DETAIL_ERROR }] = useErrorContextValue()
  const [fillDataMode, setFillDataMode] = useState(getInitialFillDataModeState())
  const [hospitalProviderList, hospitalProviderListRequest] = useGet(productsApiConfig.getHospitalProviders)

  useEffect(() => {
    window.sessionStorage.setItem('eb-products-form-fill-mode', fillDataMode)
  }, [fillDataMode])

  useEffect(() => {
    if (benefitGroupKeys[STATE_UPDATED_FROM_EXCEL]) {
      setFillDataMode(FILL_DATA_MODE.MANUAL)
    }
  }, [benefitGroupKeys])

  useEffect(() => {
    companyDetailRequest({ company_id: parmas.id })
    providerListRequest()
    hospitalProviderListRequest()
    return () => {
      resetEbState(['gcsUploadData', 'gcsUploadStatus'])
      resetError(['GCS_UPLOAD_ERROR'])
    }
  }, [])
  return (
    <PackageFormWrapper>
      <Form onSubmit={handleSubmit}>
        <Row>
          <ColTextAlignCenter>
            <Title level={4}>Add New Product</Title>
          </ColTextAlignCenter>
        </Row>
        <RowWithMargin gutter={16}>
          <Col span={12}>
            <Form.Item
              label='Company Name'
            >
              <Input
                value={!COMPANY_DETAIL_ERROR && companyDetailData && companyDetailData.data && companyDetailData.data.name}
                readOnly
                disabled
              />
            </Form.Item>
          </Col>
          <Col span={12}>
            <Form.Item label='Insurance Provider'>
              {getFieldDecorator('insurance_provider', {
                rules: [
                  { required: true, message: 'Insurance provider is required' }
                ]
              })(
                <Select
                  style={{ width: '100%' }}
                >
                  {providerListData && providerListData.providers && providerListData.providers
                    .sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()))
                    .filter(provider => !companyDetailData?.data?.unwanted_insurance?.includes(provider))
                    .map(item => (
                      <Option
                        key={item}
                        value={item}
                      >
                        {item}
                      </Option>
                    ))}
                </Select>
              )}
            </Form.Item>
          </Col>
          <Col span={12}>
            <Form.Item
              hasFeedback
              label='Total premium'
              required
            >
              {getFieldDecorator(TOTAL_PREMIUM, {
                validateTrigger: ['onBlur'],
                rules: stepOneValidationRules[TOTAL_PREMIUM]
              })(
                <CustomNumberFormat
                  decimalScale={3}
                  allowNegative={false}
                  isAllowed={({ floatValue }) => (floatValue >= 0 && floatValue <= 999999999.999) || floatValue === undefined}
                />
              )}
            </Form.Item>
          </Col>
          <Col span={12}>
            <Form.Item label='Claim Type'>
              {getFieldDecorator('claim_type', {
                rules: [
                  { required: true, message: 'Claim type is required' }
                ]
              })(
                <Select
                  style={{ width: '100%' }}
                >
                  <Option key='cashless' value='cashless'>Cashless</Option>
                  <Option key='reimbursement' value='reimbursement'>Reimbursement</Option>
                  <Option key='cashless & reimbursement' value='cashless & reimbursement'>Both</Option>
                </Select>
              )}
            </Form.Item>
          </Col>
          {
            (form.getFieldValue('claim_type') !== 'cashless') && (
              <Col
                span={12}
              >
                <Form.Item
                  hasFeedback
                  label='Reimbursement %'
                >
                  {getFieldDecorator('reimbursement_percentage', {
                    validateTrigger: 'onBlur',
                    preserve: false,
                    rules: [
                      {
                        required: ['reimbursement', 'cashless & reimbursement'].includes(form.getFieldValue('claim_type')),
                        message: 'Reimbursement % is required'
                      }
                    ]
                  })(
                    <CustomNumberFormat
                      decimalScale={0}
                      allowNegative={false}
                      isAllowed={({ floatValue }) => (floatValue > 0 && floatValue <= 100) || floatValue === undefined}
                    />
                  )}
                </Form.Item>
              </Col>

            )
          }
          <Col span={12}>
            <Form.Item label='Hospital Provider'>
              {getFieldDecorator('hospital_provider', {
                rules: [
                  { required: true, message: 'Hospital provider is required' }
                ]
              })(
                <Select
                  style={{ width: '100%' }}
                >
                  {
                    Array.isArray(hospitalProviderList?.hospital_providers) && hospitalProviderList.hospital_providers
                      .map(({ display_name: displayName, main_key: mainKey }) => (
                        <Option
                          key={mainKey}
                          value={mainKey}
                        >
                          {displayName}
                        </Option>
                      ))
                  }
                </Select>
              )}
            </Form.Item>
          </Col>
          <Col span={12}>
            <Form.Item label='Coverage End Date'>
              {getFieldDecorator('coverage_end_date', {
                rules: [
                  { required: true, message: 'Coverage end date is required' }
                ]
              })(
                <DatePicker
                  disabledDate={d => d.isBefore(moment(), 'day')}
                  format='DD-MM-YYYY'
                />
              )}
            </Form.Item>
          </Col>
        </RowWithMargin>
        <RowWithMargin>
          <Col>
            <Title level={4}>Data Entry Mode:</Title>
          </Col>
          <Col span={12} className='mt-5'>
            <Radio.Group
              onChange={e => setFillDataMode(e.target.value)}
              value={fillDataMode}
            >
              <Radio value='file'>Excel File</Radio>
              <Radio value='manual'>Manual</Radio>
            </Radio.Group>
          </Col>
        </RowWithMargin>
        {
          fillDataMode === FILL_DATA_MODE.FILE && (
            <ExcelUpload
              benefitGroupKeys={benefitGroupKeys}
              onAddBenefitGroupKey={onAddBenefitGroupKey}
              onAddBenefitKey={onAddBenefitKey}
              defaultBenefitGroups={defaultBenefitGroups}
              setStateFromExcel={setStateFromExcel}
              form={form}
              unsetStateUpdatedFromExcel={unsetStateUpdatedFromExcel}
            />
          )
        }
        <BenefitGroupContainer fillDataMode={fillDataMode}>
          <Title level={4}>Benefit Group</Title>
          <RowWithMargin>
            <Col>
              {divideArrayIntoSubArraysOfTwo(benefitGroupKeys[BG_KEYS]).map((row, rowIndex) => {
                return (
                  <Row key={rowIndex} gutter={16}>
                    {row.map(({
                      [BENEFIT_KEYS]: benefitKeys,
                      [BG_NAME]: bgName,
                      [BG_KEY]: bgKey,
                      [BG_SLUG]: bgSlug
                    }, bgIndex) => (
                      <Col key={bgKey} span={12}>
                        <RowWithMargin>
                          {getFieldDecorator(`${BENEFIT_GROUPS}.bg${bgKey}.${BG_SLUG}`, { initialValue: bgSlug })},
                          <Col span={2}>
                            {getFieldDecorator(`${BENEFIT_GROUPS}.bg${bgKey}.${IS_SELECTED}`, { valuePropName: 'checked', initialValue: (rowIndex * 2) + bgIndex === 0 })(
                              <Checkbox />
                            )}
                            {getFieldDecorator(`${BENEFIT_GROUPS}.bg${bgKey}.${BG_IDENTIFIER}`, { initialValue: bgKey })(<Input style={{ display: 'none' }} />)}
                            {getFieldDecorator(`${BENEFIT_GROUPS}.bg${bgKey}.${BG_NAME}`, { initialValue: bgName })(<Input style={{ display: 'none' }} />)}
                          </Col>
                          <Col span={14}>
                            {bgName}
                          </Col>
                          <Col span={2}>
                            <Button
                              type='link'
                              onClick={() => onRemoveBenefitGroupKey(bgKey)}
                            >
                              <Icon type='delete' theme='twoTone' twoToneColor='red' />
                            </Button>
                          </Col>
                        </RowWithMargin>
                        {benefitKeys.map((benefitKey, index) => (
                          <React.Fragment key={benefitKey}>
                            {getFieldDecorator(`${BENEFIT_GROUPS}.bg${bgKey}.${BENEFITS}.b${benefitKey}.${BENEFIT_IDENTIFIER}`, { initialValue: benefitKey })(<Input style={{ display: 'none' }} />)}
                            <Form.Item
                              required
                            >
                              <Row>
                                <Col span={18}>
                                  {getFieldDecorator(`${BENEFIT_GROUPS}.bg${bgKey}.${BENEFITS}.b${benefitKey}.${BENEFIT_NAME}`,
                                    {
                                      validateFirst: true,
                                      initialValue: '',
                                      validateTrigger: 'onBlur',
                                      rules: [{
                                        required: form.getFieldValue(`${BENEFIT_GROUPS}.bg${bgKey}.${IS_SELECTED}`),
                                        initialValue: '',
                                        message: 'Benefit is required'
                                      },
                                      {
                                        pattern: /^(?! ).*(?<! )$/,
                                        message: 'Trailing and leading spaces are not allowed'
                                      },
                                      {
                                        pattern: /^[A-Za-z].*(?<! )$/,
                                        message: 'First character should not be a special character'
                                      },
                                      {
                                        validator: (_, value) => {
                                          const bgBenefits = form.getFieldValue(`${BENEFIT_GROUPS}.bg${bgKey}.${BENEFITS}`)
                                          for (const key in bgBenefits) {
                                            if (key === `b${benefitKey}`) continue
                                            if (bgBenefits[key][BENEFIT_NAME] === value) {
                                              return Promise.reject(new Error('Benefits should be unique'))
                                            }
                                          }
                                          return Promise.resolve()
                                        }
                                      }
                                      ]
                                    })(
                                      <Input maxLength={178} />
                                  )}
                                </Col>
                                <Col offset={1} span={2}>
                                  {benefitKeys.length > 1
                                    ? (
                                      <Icon
                                        type='minus-circle'
                                        theme='twoTone'
                                        twoToneColor='red'
                                        onClick={() => onRemoveBenefitKey(bgKey, benefitKey)}
                                      />
                                      )
                                    : null}
                                  {benefitKeys.length > 0 && index === benefitKeys.length - 1
                                    ? (
                                      <Icon
                                        style={{ marginLeft: 5 }}
                                        type='plus-circle'
                                        theme='twoTone'
                                        twoToneColor='rgb(50,215,75)'
                                        onClick={() => onAddBenefitKey(bgKey)}
                                      />
                                      )
                                    : null}
                                </Col>
                              </Row>
                            </Form.Item>
                          </React.Fragment>
                        ))}
                        <Row />
                      </Col>)
                    )}
                  </Row>
                )
              })}
            </Col>
            <Col span={12}>
              <Row type='flex' justify='space-between'>
                <Col span={18}>
                  <Form.Item
                    hasFeedback
                  >
                    {getFieldDecorator('newItem', {
                      validateTrigger: ['onBlur'],
                      rules: [
                        {
                          pattern: /^(?! ).*(?<! )$/,
                          message: 'Trailing and leading spaces are not allowed'
                        },
                        {
                          min: 2,
                          message: 'Benefit group name should be of minimum 2 characters'
                        },
                        {
                          max: 128,
                          message: 'Benefit group name should be of maximum 128 characters'
                        },
                        {
                          validator: (_, value) => {
                            // TODO: check for value to be unique and validate for max and min length
                            return !benefitGroupKeys[BG_KEYS].map(({ [BG_NAME]: bgName }) => bgName).includes(value)
                              ? Promise.resolve()
                              : Promise.reject(new Error('Benefit Group already exists'))
                          }
                        }
                      ]
                    })(
                      <Input
                        placeholder='Benefit Group Name..'
                        maxLength={128}
                      />
                    )}
                  </Form.Item>
                </Col>
                <Col span={5}>
                  <Form.Item>
                    <Button
                      htmlType='button'
                      type='primary'
                      onClick={() => {
                        form.validateFields(['newItem'], {}, (err, values) => {
                          if (!err) {
                            if (values.newItem) {
                              onAddBenefitGroupKey(values.newItem)
                              form.resetFields(['newItem'])
                            } else {
                              notification.error({
                                message: 'Benefit group name cannot be empty'
                              })
                            }
                          }
                        })
                      }}
                    >
                      Add Benefit Group
                    </Button>

                  </Form.Item>
                </Col>
              </Row>
            </Col>

          </RowWithMargin>
        </BenefitGroupContainer>
        <RowWithMargin>
          {
            fillDataMode === FILL_DATA_MODE.MANUAL && (
              <ColTextAlignRight span={22}>
                <Button type='primary' htmlType='submit'>Next</Button>
              </ColTextAlignRight>
            )
          }
        </RowWithMargin>
      </Form>
    </PackageFormWrapper>
  )
}
