import React, { useState, useRef } from 'react'
import { Form, Button, Col, Row } from 'antd'
import BenefitPlansAndTSI from '../../components/benefitPlansAndTSI'
import { RowWithMargin } from '../../../../CommonComponents'
import { ColTextAlignRight } from '../../../../CommonComponents/index.style'
import { EditorState } from 'draft-js'
import { getBenefitGroups } from './utility'
import { stateToHTML } from 'draft-js-export-html'
import { stateFromHTML } from 'draft-js-import-html'
import { isEmpty } from 'lodash'

const getInitialEditorsState = (benefitGroups) => {
  let storedData = window.sessionStorage.getItem('editorsState')
  try {
    storedData = JSON.parse(storedData)
  } catch {

  }
  const state = {}
  for (const benefitGroup of benefitGroups) {
    if (storedData && storedData[benefitGroup.name]) {
      state[benefitGroup.name] = EditorState.push(EditorState.createEmpty(), stateFromHTML(storedData[benefitGroup.name]))
    } else {
      state[benefitGroup.name] = EditorState.createEmpty()
    }
  }
  return state
}

const getPlansData = () => {
  let plansData = window.sessionStorage.getItem('plansData')
  if (plansData) {
    try {
      plansData = JSON.parse(plansData)
      return plansData
    } catch {
      return {}
    }
  }
  return {}
}

const StepTwo = ({ form, next, prev }) => {
  const benefitGroups = getBenefitGroups()
  const plansData = useRef(getPlansData())
  const [editorsState, setEditorsState] = useState(getInitialEditorsState(benefitGroups))
  const [noPlansError, setNoPlansError] = useState({})

  const saveDataToSessionStroage = () => {
    const values = form.getFieldsValue()
    for (const key in values) {
      if (Array.isArray(values[key])) {
        values[key] = values[key].filter(item => !!item)
      }
    }
    window.sessionStorage.setItem('plansData', JSON.stringify(values, (k, v) => v || ''))

    const editorsStateInHtml = {}
    for (const key in editorsState) {
      editorsStateInHtml[key] = stateToHTML(editorsState[key].getCurrentContent())
    }
    window.sessionStorage.setItem('editorsState', JSON.stringify(editorsStateInHtml))
    return values
  }

  const handleGoNext = () => {
    form.validateFields(undefined, { force: true }, (err) => {
      if (!err) {
        const values = saveDataToSessionStroage()
        const noPlansError = {}
        for (const [key, value] of Object.entries(values)) {
          if (value && value.length <= 1) {
            noPlansError[key] = true
          }
        }
        setNoPlansError(noPlansError)
        if (isEmpty(noPlansError)) {
          next()
        }
      }
    }, { force: true })
  }

  const handleGoPrevious = () => {
    saveDataToSessionStroage()
    prev()
  }

  const setEditorsStateByName = (name) => {
    return (changedState) => setEditorsState(state => ({
      ...state,
      [name]: changedState
    }))
  }

  return (
    <>
      {
        benefitGroups.map(({ name, benefits, identifier, slug }) => (
          <BenefitPlansAndTSI
            key={name}
            getFieldDecorator={form.getFieldDecorator}
            benefitGroupName={name}
            benefitGroupIdentifier={identifier}
            benefitGroupSlug={slug}
            benefits={benefits}
            plansData={plansData.current[identifier]}
            form={form}
            editorsState={editorsState[name]}
            setEditorsState={setEditorsStateByName(name)}
            errors={form.getFieldError(name)}
            noPlansError={noPlansError[name]}
          />
        ))
      }
      <RowWithMargin>
        <Col offset={20} span={4}>
          <Row>
            <ColTextAlignRight span={12}>
              <Button
                type='primary'
                onClick={handleGoPrevious}
              >
                Back
              </Button>
            </ColTextAlignRight>
            <ColTextAlignRight span={12}>
              <Button
                type='primary'
                onClick={handleGoNext}
              >
                Next
              </Button>
            </ColTextAlignRight>
          </Row>
        </Col>
      </RowWithMargin>
    </>
  )
}
export default Form.create()(StepTwo)
